// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }

    function testFuzz_property(uint256 elapsed, address producer, address seller) public {
        vm.assume(producer != address(0) && seller != address(0));
        vm.assume(producer != seller);
        elapsed = bound(elapsed, 1, 1000000);

        // initialize the market
        vm.deal(producer, 1 ether);
        vm.prank(producer);
        c.seedMarket{value: 0}(1000);

        // producer gets free kilos and accumulates production over `elapsed` seconds
        vm.prank(producer);
        c.getFreeKilo();
        vm.warp(elapsed);

        // producer collects, crediting the referral (seller) with claimedDrugs = drugsUsed/5 > 0
        vm.prank(producer);
        c.collectDrugs(seller);

        uint256 credited = c.claimedDrugs(seller);
        vm.assume(credited > 0);

        // seller sells all its drugs (claimedDrugs + zero production)
        vm.prank(seller);
        c.sellDrugs();

        // RULE: after sellDrugs, the seller's claimedDrugs balance is exactly zero
        assertTrue(c.claimedDrugs(seller) == 0);
    }
}
